for lang in ('en','hi','ta','bn','te','mr','gu','kn','ml','pa'):
    I18N.setdefault(lang,{})
    for k,v in I18N['en'].items(): I18N[lang].setdefault(k,v)

def tr(language,key): return I18N.get(language,I18N['en']).get(key,I18N['en'].get(key,key))

def normalize_confidence(value):
    try: value=float(value)
    except (TypeError,ValueError): return 0.0
    if 0<=value<=1: value*=100
    return round(max(0.0,min(100.0,value)),2)

def classify_source(url,score=None):
    from urllib.parse import urlparse
    host=(urlparse(str(url or '')).hostname or '').lower()
    try: score=float(score)
    except (TypeError,ValueError): score=0.35
    # Use the same source registry as the retriever, but keep compatibility with old report data.
    for group in ('trusted_india','trusted_international'):
        for item in TRUSTED_SOURCES.get(group,[]) if isinstance(TRUSTED_SOURCES,dict) else []:
            d=item.get('domain','') if isinstance(item,dict) else ''
            if d and (host==d or host.endswith('.'+d)): return {'category':'trusted','quality':'High','score':item.get('score',0.9),'name':item.get('name',d),'group':group}
    if score>=.75: return {'category':'general','quality':'Moderate','score':score,'name':host,'group':''}
    if score>=.55: return {'category':'general','quality':'Low','score':score,'name':host,'group':''}
    return {'category':'unverified','quality':'Very low','score':score,'name':host,'group':''}

def normalize_relation(value):
    value=str(value or '').upper().strip()
    value={'ENTAILED':'SUPPORTS','SUPPORTED':'SUPPORTS','SUPPORT':'SUPPORTS','CONTRADICTED':'CONTRADICTS','CONTRADICTION':'CONTRADICTS','CONTRADICT':'CONTRADICTS'}.get(value,value)
    return value if value in {'SUPPORTS','CONTRADICTS'} else 'NEUTRAL'

def normalize_evidence(items):
    if not isinstance(items,list): return []
    out=[]
    for item in items:
        if isinstance(item,str):
            m=re.search(r'https?://\S+',item); url=m.group(0) if m else ''
            out.append({'title':item[:220],'url':url,'relation':'NEUTRAL','source_quality':classify_source(url)})
        elif isinstance(item,dict):
            url=item.get('url') or item.get('link') or ''; sq=item.get('source_quality') or classify_source(url,item.get('credibility') if item.get('credibility') is not None else item.get('score'))
            out.append({**item,'url':url,'relation':normalize_relation(item.get('relation') or item.get('stance') or item.get('label')),'source_quality':sq})
    return out

def clean_reasoning(result,language):
    text=str(result.get('localized_reasoning') or result.get('reasoning') or result.get('summary') or '').strip()
    bad=('local llm unavailable','deterministic evidence-weighted fallback used','local language model was unavailable')
    if text and not any(x in text.lower() for x in bad): return text
    evidence=normalize_evidence(result.get('evidence') or result.get('sources') or [])
    s=sum(x['relation']=='SUPPORTS' for x in evidence); c=sum(x['relation']=='CONTRADICTS' for x in evidence)
    if language=='hi': return f'उपलब्ध साक्ष्यों में {s} स्रोत समर्थन और {c} स्रोत खंडन करते हैं। निष्कर्ष केवल समान दावे से सीधे संबंधित साक्ष्य और स्रोत गुणवत्ता पर आधारित है।'
    if language=='ta': return f'கிடைத்த ஆதாரங்களில் {s} ஆதாரங்கள் ஆதரிக்கின்றன; {c} ஆதாரங்கள் முரண்படுகின்றன. முடிவு அதே கூற்றுடன் நேரடியாக தொடர்புடைய ஆதாரம் மற்றும் ஆதாரத் தரத்தை அடிப்படையாகக் கொண்டது.'
    return f'{s} reviewed source(s) support the claim and {c} contradict it. The decision uses evidence that directly matches the same claim and source quality.'

def method_text(result,language):
    fetched=bool(result.get('article_fetched'))
    status=str(result.get('llm_status') or '').upper(); provider=str(result.get('provider','')).lower()
    if language=='hi':
        return ('लाइव वेब स्रोत, समान-दावे मिलान, स्रोत गुणवत्ता, स्वतंत्र स्रोत सहमति और इमेज संदर्भ की जाँच की गई।' if fetched else 'लाइव वेब स्रोत, समान-दावे मिलान, स्रोत गुणवत्ता, स्वतंत्र स्रोत सहमति और इमेज संदर्भ की जाँच की गई।') + ((' स्थानीय भाषा मॉडल का उपयोग केवल व्याख्या के लिए किया गया।' if status=='OK' or provider=='ollama' else ' स्थानीय भाषा मॉडल उपलब्ध न होने पर निर्धारक साक्ष्य नियम लागू किए गए।'))
    if language=='ta': return 'நேரடி வலை ஆதாரங்கள், அதே கூற்று பொருத்தம், ஆதார தரம், சுயாதீன ஆதார ஒற்றுமை மற்றும் பட சூழல் சரிபார்க்கப்பட்டது.'
